def is_sigma_busy(t_start, t_end, N, sigma, task_set):
    load = calculate_load(task_set, t_start, t_end, N) # From Definition 2
    return load >= N * (1 - sigma) + sigma

def find_maximal_sigma_busy_extension(t_problem_start, t_problem_end, N, sigma, task_set):
    maximal_start = t_problem_start
    current_start = t_problem_start
    while current_start > SYSTEM_START_TIME:
        if is_sigma_busy(current_start, t_problem_end, N, sigma, task_set):
            maximal_start = current_start
            current_start -= TIME_STEP # Move further back
        else:
            break
    return (maximal_start, t_problem_end)

def find_unique_maximal_busy_window(problem_interval_start, problem_interval_end, N, sigma, task_set):
    # This function relies on the existence proof from the lemma.
    # It's a conceptual function to find the window.
    # The actual implementation would be similar to find_maximal_sigma_busy_extension in Definition 6.
    busy_window_start, busy_window_end = find_maximal_sigma_busy_extension(problem_interval_start, problem_interval_end, N, sigma, task_set)
    return (busy_window_start, busy_window_end)

def get_busy_window(problem_window_start, problem_window_end, N, sigma, task_set):
    # This is a direct application of Lemma 7
    busy_window_start, busy_window_end = find_unique_maximal_busy_window(problem_window_start, problem_window_end, N, sigma, task_set)
    return (busy_window_start, busy_window_end)

def bound_carry_in_in_busy_window(task_i, busy_window_start, C_i):
    # This lemma states that carry_in_i is at most C_i.
    # The actual proof in the full paper might derive a tighter bound based on sigma-busy property.
    # For the purpose of this summary, we use the stated upper bound.
    carry_in_i = calculate_carry_in(task_i, busy_window_start, schedule_history) # From Definition 4
    if carry_in_i > 0:
        return min(carry_in_i, C_i) # The lemma states it's between 0 and C_i
    else:
        return 0

def calculate_edf_demand_bound_for_task(task_i, interval_length, carry_in_i_head):
    num_jobs_i = 0
    if interval_length >= task_i.D:
        num_jobs_i = math.floor((interval_length - task_i.D) / task_i.T) + 1

    demand_i = num_jobs_i * task_i.C + carry_in_i_head
    return demand_i

def calculate_edf_lambda(task_i, interval_length):
    lambda_i = 0
    if task_i.D <= interval_length:
        # C_i for carry-in job + (number of full jobs) * C_i
        lambda_i = task_i.C + math.floor((interval_length - task_i.D) / task_i.T) * task_i.C
    else:
        # Only a carry-in job can contribute
        lambda_i = task_i.C
    return lambda_i

def calculate_dm_lambda(task_i, task_k, interval_length):
    tail_length_i = 0
    if task_i.D < task_k.D:
        tail_length_i = task_i.D
    else:
        tail_length_i = task_k.D

    lambda_i = 0
    if tail_length_i <= interval_length:
        lambda_i = task_i.C + math.floor((interval_length - tail_length_i) / task_i.T) * task_i.C
    else:
        lambda_i = task_i.C
    return lambda_i

def check_sb_edf_schedulability(task_set, N):
    U_total = 0
    U_max = 0
    for task_i in task_set:
        U_i = task_i.C / task_i.T
        U_total += U_i
        if U_i > U_max:
            U_max = U_i

    bound_factor = (3 * N - 2) / (3 * N - 1)

    if U_total <= N * bound_factor and U_max <= bound_factor:
        print("Srinivasan-Baruah EDF Schedulability PASSED")
        return True
    else:
        print("Srinivasan-Baruah EDF Schedulability FAILED")
        return False

def check_dm_schedulability(task_set, N):
    for task_k in task_set:
        sigma_k = task_k.C / task_k.D
        critical_interval_lengths = generate_critical_lengths(task_set, task_k.D) # Similar to EDF

        for interval_length_k in critical_interval_lengths:
            RHS = N * (1 - sigma_k) + sigma_k
            LHS = 0
            for task_i in task_set:
                LHS += calculate_dm_lambda(task_i, task_k, interval_length_k) # From Lemma 17

            if LHS > RHS:
                print(f"DM Schedulability FAILED for task {task_k.id} at interval length {interval_length_k}")
                return False
    print("DM Schedulability PASSED")
    return True

def check_abj_rm_schedulability(task_set, N):
    U_total = 0
    U_max = 0
    for task_i in task_set:
        U_i = task_i.C / task_i.T
        U_total += U_i
        if U_i > U_max:
            U_max = U_i

    bound_factor = (3 * N - 2) / (3 * N - 1)

    if U_total <= N * bound_factor and U_max <= bound_factor:
        print("Andersson-Baruah-Jonsson RM Schedulability PASSED")
        return True
    else:
        print("Andersson-Baruah-Jonsson RM Schedulability FAILED")
        return False

def check_us_schedulability(task_set, N, alpha, algorithm_type):
    U_total = 0
    for task_i in task_set:
        U_total += task_i.C / task_i.T

    if U_total <= N * alpha:
        print(f"Algorithm {algorithm_type}-US[{alpha}] Schedulability PASSED")
        return True
    else:
        print(f"Algorithm {algorithm_type}-US[{alpha}] Schedulability FAILED")
        return False

def check_generalized_us_schedulability(task_set, N, alpha, algorithm_type):
    heavy_tasks = []
    light_tasks = []
    for task_i in task_set:
        if (task_i.C / task_i.T) > alpha:
            heavy_tasks.append(task_i)
        else:
            light_tasks.append(task_i)

    k = len(heavy_tasks)
    if k > N:
        print("Too many heavy tasks for available processors.")
        return False

    U_remaining_tasks = 0
    for task_i in light_tasks:
        U_remaining_tasks += (task_i.C / task_i.T)

    # The bound (N - k) * (1 - alpha) + alpha * (N - k) simplifies to (N - k)
    # This implies the remaining N-k processors can handle the remaining tasks.
    if U_remaining_tasks <= (N - k):
        print(f"Algorithm {algorithm_type}-US[{alpha}] Generalized Schedulability PASSED")
        return True
    else:
        print(f"Algorithm {algorithm_type}-US[{alpha}] Generalized Schedulability FAILED")
        return False

def check_simplified_edf_schedulability(task_set, N):
    U_total = 0
    U_max = 0
    for task_i in task_set:
        U_i = task_i.C / task_i.T
        U_total += U_i
        if U_i > U_max:
            U_max = U_i

    bound = N * (1 - U_max) + U_max

    if U_total <= bound:
        print("Simplified EDF Schedulability PASSED")
        return True
    else:
        print("Simplified EDF Schedulability FAILED")
        return False

def check_gfb_edf_schedulability(task_set, N):
    for task_i in task_set:
        if task_i.D != task_i.T:
            print("GFB EDF Schedulability requires D_i = T_i for all tasks.")
            return False

    # This is identical to check_simplified_edf_schedulability once D_i = T_i is assumed.
    return check_simplified_edf_schedulability(task_set, N)

