def check_rm_utilization_bound(task_set, N):
    if N < 2:
        print("RM Utilization Bound requires N >= 2.")
        return False
    for task_i in task_set:
        if task_i.D != task_i.T:
            print("RM Utilization Bound requires D_i = T_i for all tasks.")
            return False

    # This is identical to check_simplified_dm_schedulability once D_i = T_i is assumed.
    return check_simplified_dm_schedulability(task_set, N)

def check_bg_rm_schedulability(task_set, N):
    U_total = 0
    for task_i in task_set:
        if task_i.D != task_i.T:
            print("Baruah-Goossens RM Schedulability requires D_i = T_i for all tasks.")
            return False
        U_i = task_i.C / task_i.T
        if U_i > 0.5:
            print(f"Baruah-Goossens RM Schedulability requires U_i <= 0.5 for all tasks. Task {task_i.id} fails.")
            return False
        U_total += U_i

    if U_total <= N / 2:
        print("Baruah-Goossens RM Schedulability PASSED")
        return True
    else:
        print("Baruah-Goossens RM Schedulability FAILED")
        return False
